--
-- Name: add_challenge_comment(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.add_challenge_comment(p_challenge_id uuid, p_comment_text text, p_parent_comment_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_comment_id uuid;
  v_user_id uuid;
  v_actual_parent_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.challenges
    WHERE id = p_challenge_id
      AND (is_active = true OR public.is_admin())
  ) THEN
    RAISE EXCEPTION 'Challenge not found';
  END IF;

  IF p_parent_comment_id IS NOT NULL THEN
    SELECT COALESCE(parent_comment_id, id) INTO v_actual_parent_id
    FROM public.comments
    WHERE id = p_parent_comment_id
      AND deleted_at IS NULL;

    IF v_actual_parent_id IS NULL THEN
      RAISE EXCEPTION 'Parent comment not found or deleted';
    END IF;
  END IF;

  VALUES (v_user_id, p_comment_text, v_actual_parent_id)
  RETURNING id INTO v_comment_id;

  VALUES (p_challenge_id, v_comment_id);

  RETURN v_comment_id;
END;
$$;


ALTER FUNCTION public.add_challenge_comment(p_challenge_id uuid, p_comment_text text, p_parent_comment_id uuid) OWNER TO supabase_admin;

