--
-- Name: add_comment(text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.add_comment(p_entity_type text, p_entity_id uuid, p_comment_text text, p_parent_comment_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_comment_id uuid;
  v_user_id uuid;
  v_actual_parent_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_entity_type = 'album' THEN
    IF NOT public.can_comment_on_album(p_entity_id) THEN
      RAISE EXCEPTION 'Not authorized to comment on this album';
    END IF;
  ELSIF p_entity_type = 'photo' THEN
    IF NOT public.can_comment_on_photo(p_entity_id) THEN
      RAISE EXCEPTION 'Not authorized to comment on this photo';
    END IF;
  ELSE
    RAISE EXCEPTION 'Invalid entity type: %', p_entity_type;
  END IF;

  IF p_parent_comment_id IS NOT NULL THEN
    SELECT COALESCE(parent_comment_id, id) INTO v_actual_parent_id
    FROM comments
    WHERE id = p_parent_comment_id
      AND deleted_at IS NULL;

    IF v_actual_parent_id IS NULL THEN
      RAISE EXCEPTION 'Parent comment not found or deleted';
    END IF;
  END IF;

  VALUES (v_user_id, p_comment_text, v_actual_parent_id)
  RETURNING id INTO v_comment_id;

  IF p_entity_type = 'album' THEN
    VALUES (p_entity_id, v_comment_id);
  ELSE
    VALUES (p_entity_id, v_comment_id);
  END IF;

  RETURN v_comment_id;
END;
$$;


ALTER FUNCTION public.add_comment(p_entity_type text, p_entity_id uuid, p_comment_text text, p_parent_comment_id uuid) OWNER TO supabase_admin;

