--
-- Name: admin_delete_album(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.admin_delete_album(p_album_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_is_admin BOOLEAN;
  v_comment_ids UUID[];
BEGIN
  -- Get the current user
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Verify the user is an admin
  SELECT is_admin INTO v_is_admin
  FROM profiles
  WHERE id = v_user_id;

  IF NOT v_is_admin THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  -- Check album exists and is not already deleted
  IF NOT EXISTS (SELECT 1 FROM albums WHERE id = p_album_id AND deleted_at IS NULL) THEN
    RETURN FALSE; -- Album not found or already deleted
  END IF;

  -- Get all comment IDs linked to this album
  SELECT ARRAY_AGG(ac.comment_id) INTO v_comment_ids
  FROM album_comments ac
  JOIN comments c ON c.id = ac.comment_id
  WHERE ac.album_id = p_album_id AND c.deleted_at IS NULL;

  -- Soft delete the actual comments
  IF v_comment_ids IS NOT NULL AND array_length(v_comment_ids, 1) > 0 THEN
    UPDATE comments 
    SET deleted_at = NOW() 
    WHERE id = ANY(v_comment_ids) AND deleted_at IS NULL;
  END IF;

  -- Soft delete the album
  UPDATE albums 
  SET deleted_at = NOW() 
  WHERE id = p_album_id;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION public.admin_delete_album(p_album_id uuid) OWNER TO supabase_admin;

--
-- Name: FUNCTION admin_delete_album(p_album_id uuid); Type: COMMENT; Schema: public; Owner: supabase_admin
--

COMMENT ON FUNCTION public.admin_delete_album(p_album_id uuid) IS 'Admin-only: Soft deletes any album and related comments by setting deleted_at timestamp';


--
-- Name: auto_assign_album_photo_sort_order(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.auto_assign_album_photo_sort_order() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  -- Only auto-assign if sort_order is not provided or is null
  IF NEW.sort_order IS NULL THEN
    SELECT COALESCE(MAX(sort_order), -1) + 1 INTO NEW.sort_order
    FROM public.album_photos
    WHERE album_id = NEW.album_id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.auto_assign_album_photo_sort_order() OWNER TO supabase_admin;

--
-- Name: FUNCTION auto_assign_album_photo_sort_order(); Type: COMMENT; Schema: public; Owner: supabase_admin
--

COMMENT ON FUNCTION public.auto_assign_album_photo_sort_order() IS 'Auto-assigns sort_order to new album_photos based on current max + 1';


--
-- Name: batch_update_album_photos(jsonb); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.batch_update_album_photos(photo_updates jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_is_admin boolean;
  v_album_id uuid;
  v_album_user_id uuid;
  v_unauthorized_count integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT public.is_admin() INTO v_is_admin;

  SELECT ap.album_id, a.user_id
  INTO v_album_id, v_album_user_id
  FROM public.album_photos ap
  JOIN public.albums a ON a.id = ap.album_id
  WHERE ap.id = ((photo_updates->0)->>'id')::uuid;

  IF v_album_id IS NULL THEN
    RAISE EXCEPTION 'Album photo not found';
  END IF;

  SELECT COUNT(*) INTO v_unauthorized_count
  FROM jsonb_array_elements(photo_updates) AS update_item
  LEFT JOIN public.album_photos ap
    ON ap.id = (update_item->>'id')::uuid
   AND ap.album_id = v_album_id
  WHERE ap.id IS NULL;

  IF v_unauthorized_count > 0 THEN
    RAISE EXCEPTION 'Not authorized to update album photos';
  END IF;

  IF v_album_user_id IS NOT NULL AND v_album_user_id <> auth.uid() AND NOT v_is_admin THEN
    RAISE EXCEPTION 'Not authorized to update album photos';
  END IF;

  IF v_album_user_id IS NULL AND NOT v_is_admin THEN
    RAISE EXCEPTION 'Not authorized to update album photos';
  END IF;

  UPDATE public.album_photos
  SET
    title = COALESCE(update_item->>'title', public.album_photos.title),
    sort_order = COALESCE((update_item->>'sort_order')::int, public.album_photos.sort_order)
  FROM jsonb_array_elements(photo_updates) AS update_item
  WHERE public.album_photos.id = (update_item->>'id')::uuid;
END;
$$;


ALTER FUNCTION public.batch_update_album_photos(photo_updates jsonb) OWNER TO supabase_admin;

--
-- Name: FUNCTION batch_update_album_photos(photo_updates jsonb); Type: COMMENT; Schema: public; Owner: supabase_admin
--

COMMENT ON FUNCTION public.batch_update_album_photos(photo_updates jsonb) IS 'Batch update album photo titles/sort order (owner or admin)';


--
-- Name: batch_update_photos(jsonb); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.batch_update_photos(photo_updates jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.photos
  SET 
    title = COALESCE(update_item->>'title', public.photos.title),
    description = COALESCE(update_item->>'description', public.photos.description),
    is_public = COALESCE((update_item->>'is_public')::boolean, public.photos.is_public),
    sort_order = COALESCE((update_item->>'sort_order')::int, public.photos.sort_order),
    license = COALESCE((update_item->>'license')::public.license_type, public.photos.license)
  FROM jsonb_array_elements(photo_updates) AS update_item
  WHERE public.photos.id = (update_item->>'id')::uuid
    AND public.photos.user_id = auth.uid();
END;
$$;


ALTER FUNCTION public.batch_update_photos(photo_updates jsonb) OWNER TO supabase_admin;

--
-- Name: bulk_delete_photos(uuid[]); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.bulk_delete_photos(p_photo_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_deleted_count INTEGER;
BEGIN
  -- Get the current user
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Soft delete photos owned by the user
  -- Note: Storage files need to be deleted separately by the client
  -- because we can't access storage from SQL functions
  WITH updated AS (
    UPDATE photos
    SET deleted_at = NOW()
    WHERE id = ANY(p_photo_ids)
      AND user_id = v_user_id
      AND deleted_at IS NULL
    RETURNING id
  )
  SELECT COUNT(*) INTO v_deleted_count FROM updated;

  RETURN v_deleted_count;
END;
$$;


ALTER FUNCTION public.bulk_delete_photos(p_photo_ids uuid[]) OWNER TO supabase_admin;

--
-- Name: FUNCTION bulk_delete_photos(p_photo_ids uuid[]); Type: COMMENT; Schema: public; Owner: supabase_admin
--

COMMENT ON FUNCTION public.bulk_delete_photos(p_photo_ids uuid[]) IS 'Soft deletes multiple photos owned by the current user by setting deleted_at timestamp';


--
-- Name: bulk_remove_from_album(uuid[]); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.bulk_remove_from_album(p_album_photo_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_is_admin boolean;
  v_album_id uuid;
  v_album_user_id uuid;
  v_deleted_count integer;
  v_unauthorized_count integer;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT public.is_admin() INTO v_is_admin;

  SELECT ap.album_id, a.user_id
  INTO v_album_id, v_album_user_id
  FROM public.album_photos ap
  JOIN public.albums a ON a.id = ap.album_id
  WHERE ap.id = p_album_photo_ids[1];

  IF v_album_id IS NULL THEN
    RAISE EXCEPTION 'Album photo not found';
  END IF;

  SELECT COUNT(*) INTO v_unauthorized_count
  FROM unnest(p_album_photo_ids) AS requested_id
  LEFT JOIN public.album_photos ap
    ON ap.id = requested_id
   AND ap.album_id = v_album_id
  WHERE ap.id IS NULL;

  IF v_unauthorized_count > 0 THEN
    RAISE EXCEPTION 'Not authorized to modify this album';
  END IF;

  IF v_album_user_id IS NULL THEN
    IF NOT v_is_admin THEN
      RAISE EXCEPTION 'Not authorized to modify this album';
    END IF;
  ELSIF v_album_user_id <> v_user_id AND NOT v_is_admin THEN
    RAISE EXCEPTION 'Not authorized to modify this album';
  END IF;

  WITH deleted AS (
    DELETE FROM public.album_photos
    WHERE id = ANY(p_album_photo_ids)
    RETURNING id
  )
  SELECT COUNT(*) INTO v_deleted_count FROM deleted;

  RETURN v_deleted_count;
END;
$$;


ALTER FUNCTION public.bulk_remove_from_album(p_album_photo_ids uuid[]) OWNER TO supabase_admin;

--
-- Name: FUNCTION bulk_remove_from_album(p_album_photo_ids uuid[]); Type: COMMENT; Schema: public; Owner: supabase_admin
--

COMMENT ON FUNCTION public.bulk_remove_from_album(p_album_photo_ids uuid[]) IS 'Removes multiple photos from an album (owner or admin)';


--
-- Name: bulk_review_challenge_submissions(uuid[], text, text); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.bulk_review_challenge_submissions(p_submission_ids uuid[], p_status text, p_rejection_reason text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_is_admin BOOLEAN;
    v_updated INTEGER := 0;
BEGIN
    -- Verify user is authenticated
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    -- Verify user is admin
    SELECT is_admin INTO v_is_admin
    FROM "public"."profiles"
    WHERE id = v_user_id;

    IF NOT v_is_admin THEN
        RAISE EXCEPTION 'Admin access required';
    END IF;

    -- Validate status
    IF p_status NOT IN ('pending', 'accepted', 'rejected') THEN
        RAISE EXCEPTION 'Invalid status. Must be pending, accepted, or rejected';
    END IF;

    -- Update submissions
    UPDATE "public"."challenge_submissions"
    SET status = p_status,
        reviewed_at = now(),
        reviewed_by = v_user_id,
        rejection_reason = CASE WHEN p_status = 'rejected' THEN p_rejection_reason ELSE NULL END
    WHERE id = ANY(p_submission_ids);

    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN v_updated;
END;
$$;


ALTER FUNCTION public.bulk_review_challenge_submissions(p_submission_ids uuid[], p_status text, p_rejection_reason text) OWNER TO supabase_admin;

--
-- Name: FUNCTION bulk_review_challenge_submissions(p_submission_ids uuid[], p_status text, p_rejection_reason text); Type: COMMENT; Schema: public; Owner: supabase_admin
--

COMMENT ON FUNCTION public.bulk_review_challenge_submissions(p_submission_ids uuid[], p_status text, p_rejection_reason text) IS 'Bulk review challenge submissions (admin only)';


--
-- Name: can_comment_on_album(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.can_comment_on_album(p_album_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.albums a
    WHERE a.id = p_album_id
      AND a.deleted_at IS NULL
      AND (
        a.user_id = auth.uid()
        OR (a.is_public = true AND COALESCE(a.is_suspended, false) = false)
        OR public.is_shared_album_member(a.id, auth.uid())
        OR public.is_admin()
      )
  );
$$;


