-- Name: get_photo_exif(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_photo_exif(p_photo_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT p.exif_data INTO v_result
  FROM public.photos p
  WHERE p.id = p_photo_id
    AND p.deleted_at IS NULL
    AND (
      p.user_id = auth.uid()
      OR public.is_admin()
    );

  RETURN v_result;
END;
