--
-- Name: get_profile_stats(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_profile_stats(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN jsonb_build_object(
    'eventsAttended', (
      SELECT COUNT(*)::int FROM events_rsvps
      WHERE user_id = p_user_id
        AND attended_at IS NOT NULL
        AND confirmed_at IS NOT NULL
        AND canceled_at IS NULL
    ),
    'commentsMade', (
      SELECT COUNT(DISTINCT c.id)::int
      FROM comments c
      WHERE c.user_id = p_user_id
        AND c.deleted_at IS NULL
        AND (
          EXISTS (
            SELECT 1 FROM album_comments ac
            JOIN albums a ON a.id = ac.album_id
            WHERE ac.comment_id = c.id
              AND a.is_public = true
              AND a.deleted_at IS NULL
          )
          OR EXISTS (
            SELECT 1 FROM photo_comments pc
            JOIN photos p ON p.id = pc.photo_id
            WHERE pc.comment_id = c.id
              AND p.is_public = true
              AND p.deleted_at IS NULL
          )
          OR EXISTS (SELECT 1 FROM event_comments ec WHERE ec.comment_id = c.id)
          OR EXISTS (
            SELECT 1 FROM challenge_comments cc
            JOIN challenges ch ON ch.id = cc.challenge_id
            WHERE cc.comment_id = c.id AND ch.is_active = true
          )
          OR EXISTS (
            SELECT 1 FROM scene_event_comments sec
            JOIN scene_events se ON se.id = sec.scene_event_id
            WHERE sec.comment_id = c.id AND se.deleted_at IS NULL
          )
        )
    ),
    'commentsReceived', (
      SELECT COUNT(DISTINCT c.id)::int FROM comments c
      WHERE c.deleted_at IS NULL
        AND c.user_id != p_user_id
        AND (
          c.id IN (
            SELECT ac.comment_id
            FROM album_comments ac
            JOIN albums a ON a.id = ac.album_id
            WHERE a.user_id = p_user_id
              AND a.is_public = true
              AND a.deleted_at IS NULL
          )
          OR c.id IN (
            SELECT pc.comment_id
            FROM photo_comments pc
            JOIN photos p ON p.id = pc.photo_id
            WHERE p.user_id = p_user_id
              AND p.is_public = true
              AND p.deleted_at IS NULL
              AND p.storage_path NOT LIKE 'events/%'
          )
        )
    ),
    'likesReceived', (
      COALESCE((
        SELECT SUM(likes_count)::int FROM albums
        WHERE user_id = p_user_id AND is_public = true AND deleted_at IS NULL
      ), 0) +
      COALESCE((
        SELECT SUM(likes_count)::int FROM photos
        WHERE user_id = p_user_id AND is_public = true AND deleted_at IS NULL
      ), 0)
    ),
    'likesGiven', (
      COALESCE((SELECT COUNT(*)::int FROM album_likes WHERE user_id = p_user_id), 0) +
      COALESCE((SELECT COUNT(*)::int FROM photo_likes WHERE user_id = p_user_id), 0)
    ),
    'viewsReceived', (
      COALESCE((
        SELECT SUM(view_count)::int FROM albums
        WHERE user_id = p_user_id AND is_public = true AND deleted_at IS NULL
      ), 0) +
      COALESCE((
        SELECT SUM(view_count)::int FROM photos
        WHERE user_id = p_user_id AND is_public = true AND deleted_at IS NULL
      ), 0)
    ),
    'challengesParticipated', (
      SELECT COUNT(DISTINCT cs.challenge_id)::int
      FROM challenge_submissions cs
      JOIN photos p ON p.id = cs.photo_id
      WHERE cs.user_id = p_user_id
        AND cs.status = 'accepted'
        AND p.deleted_at IS NULL
    ),
    'challengePhotosAccepted', (
      SELECT COUNT(*)::int FROM challenge_submissions cs
      JOIN photos p ON p.id = cs.photo_id
      WHERE cs.user_id = p_user_id AND cs.status = 'accepted' AND p.deleted_at IS NULL
    )
  );
END;
$$;


ALTER FUNCTION public.get_profile_stats(p_user_id uuid) OWNER TO supabase_admin;

--
-- Name: FUNCTION get_profile_stats(p_user_id uuid); Type: COMMENT; Schema: public; Owner: supabase_admin
--

COMMENT ON FUNCTION public.get_profile_stats(p_user_id uuid) IS 'Returns public profile stats in a single query. Replaces 12+ individual queries. Used by getProfileStats().';


--
-- Name: get_rsvp_by_uuid(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_rsvp_by_uuid(p_uuid uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'rsvp', (
      to_jsonb(r)
      - 'ip_address'
    ),
    'event', to_jsonb(e)
  )
  INTO v_result
  FROM public.events_rsvps r
  JOIN public.events e ON e.id = r.event_id
  WHERE r.uuid = p_uuid;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_rsvp_by_uuid(p_uuid uuid) OWNER TO supabase_admin;

--
-- Name: get_stats_time_series(text, timestamp with time zone, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_stats_time_series(p_metric text, p_start timestamp with time zone, p_end timestamp with time zone, p_bucket text DEFAULT 'day'::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_trunc text;
  v_step interval;
  v_date_fmt text;
  v_result jsonb;
  v_caller uuid := auth.uid();
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_user_id IS NOT NULL AND v_caller <> p_user_id AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF p_user_id IS NULL AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  v_trunc := CASE
    WHEN p_bucket = 'hour' THEN 'hour'
    WHEN p_bucket = 'month' THEN 'month'
    WHEN p_bucket = 'week' THEN 'week'
    ELSE 'day'
  END;

  v_step := CASE v_trunc
    WHEN 'hour' THEN interval '1 hour'
    WHEN 'month' THEN interval '1 month'
    WHEN 'week' THEN interval '1 week'
    ELSE interval '1 day'
  END;

  v_date_fmt := CASE
    WHEN v_trunc = 'hour' THEN 'YYYY-MM-DD"T"HH24":00"'
    ELSE 'YYYY-MM-DD'
  END;

  IF p_metric = 'signups' THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'date', to_char(timezone('UTC', date_trunc(v_trunc, created_at)), v_date_fmt),
      'value', cnt
    ) ORDER BY date_trunc(v_trunc, created_at)), '[]'::jsonb)
    INTO v_result
    FROM (
      SELECT date_trunc(v_trunc, created_at) AS bucket, COUNT(*)::int AS cnt
      FROM profiles
      WHERE created_at >= p_start AND created_at <= p_end
      GROUP BY 1
    ) s;

  ELSIF p_metric = 'uploads' THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'date', to_char(timezone('UTC', bucket), v_date_fmt),
      'value', cnt
    ) ORDER BY bucket), '[]'::jsonb)
    INTO v_result
    FROM (
      SELECT date_trunc(v_trunc, created_at) AS bucket, COUNT(*)::int AS cnt
      FROM photos
      WHERE deleted_at IS NULL
        AND created_at >= p_start AND created_at <= p_end
        AND (p_user_id IS NULL OR user_id = p_user_id)
      GROUP BY 1
    ) s;

  ELSIF p_metric = 'views' THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'date', to_char(timezone('UTC', bucket), v_date_fmt),
      'value', cnt
    ) ORDER BY bucket), '[]'::jsonb)
    INTO v_result
    FROM (
      SELECT date_trunc(v_trunc, viewed_at) AS bucket, COUNT(*)::int AS cnt
      FROM (
        SELECT pv.viewed_at FROM photo_views pv
        JOIN photos p ON p.id = pv.photo_id
        WHERE pv.viewed_at >= p_start AND pv.viewed_at <= p_end
          AND p.deleted_at IS NULL
          AND (p_user_id IS NULL OR p.user_id = p_user_id)
        UNION ALL
        SELECT av.viewed_at FROM album_views av
        JOIN albums a ON a.id = av.album_id
        WHERE av.viewed_at >= p_start AND av.viewed_at <= p_end
          AND a.deleted_at IS NULL
          AND (p_user_id IS NULL OR a.user_id = p_user_id)
      ) v
      GROUP BY date_trunc(v_trunc, viewed_at)
    ) s;

  ELSIF p_metric = 'likes' THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'date', to_char(timezone('UTC', bucket), v_date_fmt),
      'value', cnt
    ) ORDER BY bucket), '[]'::jsonb)
    INTO v_result
    FROM (
      SELECT date_trunc(v_trunc, created_at) AS bucket, COUNT(*)::int AS cnt
      FROM (
        SELECT pl.created_at FROM photo_likes pl
        JOIN photos p ON p.id = pl.photo_id
        WHERE pl.created_at >= p_start AND pl.created_at <= p_end
          AND p.deleted_at IS NULL
          AND (p_user_id IS NULL OR p.user_id = p_user_id)
        UNION ALL
        SELECT al.created_at FROM album_likes al
        JOIN albums a ON a.id = al.album_id
        WHERE al.created_at >= p_start AND al.created_at <= p_end
          AND a.deleted_at IS NULL
          AND (p_user_id IS NULL OR a.user_id = p_user_id)
      ) l
      GROUP BY date_trunc(v_trunc, created_at)
    ) s;

  ELSIF p_metric = 'comments' THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'date', to_char(timezone('UTC', bucket), v_date_fmt),
      'value', cnt
    ) ORDER BY bucket), '[]'::jsonb)
    INTO v_result
    FROM (
      SELECT date_trunc(v_trunc, c.created_at) AS bucket, COUNT(*)::int AS cnt
      FROM comments c
      WHERE c.deleted_at IS NULL
        AND c.created_at >= p_start AND c.created_at <= p_end
        AND (p_user_id IS NULL OR c.user_id = p_user_id)
      GROUP BY 1
    ) s;

  ELSIF p_metric = 'storage_added' THEN
    -- Absolute storage at the end of each bucket, including photos uploaded
    -- before the range (so week/month charts start at the then-current total).
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'date', to_char(s.bucket, v_date_fmt),
      'value', s.total
    ) ORDER BY s.bucket), '[]'::jsonb)
    INTO v_result
    FROM (
      SELECT
        gs.bucket,
        COALESCE(SUM(p.file_size), 0)::bigint AS total
      FROM generate_series(
        date_trunc(v_trunc, p_start AT TIME ZONE 'UTC'),
        date_trunc(v_trunc, p_end AT TIME ZONE 'UTC'),
        v_step
      ) AS gs(bucket)
      LEFT JOIN photos p ON
        (p_user_id IS NULL OR p.user_id = p_user_id)
        AND (p.created_at AT TIME ZONE 'UTC') < gs.bucket + v_step
        AND (
          p.deleted_at IS NULL
          OR (p.deleted_at AT TIME ZONE 'UTC') >= gs.bucket + v_step
        )
      GROUP BY gs.bucket
    ) s;

  ELSIF p_metric = 'photos_deleted' THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'date', to_char(timezone('UTC', bucket), v_date_fmt),
      'value', cnt
    ) ORDER BY bucket), '[]'::jsonb)
    INTO v_result
    FROM (
      SELECT date_trunc(v_trunc, deleted_at) AS bucket, COUNT(*)::int AS cnt
      FROM photos
      WHERE deleted_at IS NOT NULL
        AND deleted_at >= p_start AND deleted_at <= p_end
        AND (p_user_id IS NULL OR user_id = p_user_id)
      GROUP BY 1
    ) s;

  ELSIF p_metric = 'followers_gained' AND p_user_id IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'date', to_char(timezone('UTC', bucket), v_date_fmt),
      'value', cnt
    ) ORDER BY bucket), '[]'::jsonb)
    INTO v_result
    FROM (
      SELECT date_trunc(v_trunc, created_at) AS bucket, COUNT(*)::int AS cnt
      FROM follows
      WHERE following_id = p_user_id
        AND created_at >= p_start AND created_at <= p_end
      GROUP BY 1
    ) s;

  ELSE
    RAISE EXCEPTION 'Unknown metric: %', p_metric;
  END IF;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.get_stats_time_series(p_metric text, p_start timestamp with time zone, p_end timestamp with time zone, p_bucket text, p_user_id uuid) OWNER TO supabase_admin;

--
-- Name: get_user_album_photos_count(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_user_album_photos_count(user_uuid uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT COUNT(*)::INTEGER
  FROM public.album_photos_active ap
  WHERE ap.album_id IN (
    SELECT id 
    FROM public.albums 
    WHERE user_id = user_uuid 
    AND deleted_at IS NULL
  );
$$;


