--
-- Name: get_user_stats(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_user_stats(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_album_ids uuid[];
  v_photo_ids uuid[];
  v_result jsonb;
  v_caller uuid := auth.uid();
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF v_caller <> p_user_id AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_album_ids
  FROM albums
  WHERE user_id = p_user_id AND deleted_at IS NULL;

  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_photo_ids
  FROM photos
  WHERE user_id = p_user_id
    AND deleted_at IS NULL
    AND storage_path NOT LIKE 'events/%';

  SELECT jsonb_build_object(
    'albums', COALESCE(array_length(v_album_ids, 1), 0),
    'photos', COALESCE(array_length(v_photo_ids, 1), 0),
    'commentsMade', (
      SELECT COUNT(*)::int FROM comments
      WHERE user_id = p_user_id AND deleted_at IS NULL
    ),
    'commentsReceived', (
      SELECT COUNT(*)::int FROM comments c
      WHERE c.deleted_at IS NULL
        AND c.user_id != p_user_id
        AND (
          c.id IN (SELECT comment_id FROM album_comments WHERE album_id = ANY(v_album_ids))
          OR c.id IN (SELECT comment_id FROM photo_comments WHERE photo_id = ANY(v_photo_ids))
        )
    ),
    'likesReceived', (
      COALESCE((SELECT SUM(likes_count)::int FROM albums WHERE user_id = p_user_id AND deleted_at IS NULL), 0) +
      COALESCE((SELECT SUM(p.likes_count)::int FROM photos p WHERE p.id = ANY(v_photo_ids) AND p.deleted_at IS NULL), 0)
    ),
    'likesMade', (
      (SELECT COUNT(*)::int FROM album_likes al
       JOIN albums a ON a.id = al.album_id
       WHERE al.user_id = p_user_id AND a.deleted_at IS NULL) +
      (SELECT COUNT(*)::int FROM photo_likes pl
       JOIN photos p ON p.id = pl.photo_id
       WHERE pl.user_id = p_user_id AND p.deleted_at IS NULL)
    ),
    'viewsReceived', (
      COALESCE((SELECT SUM(view_count)::int FROM albums WHERE user_id = p_user_id AND is_public = true AND deleted_at IS NULL), 0) +
      COALESCE((SELECT SUM(view_count)::int FROM photos WHERE user_id = p_user_id AND is_public = true AND deleted_at IS NULL), 0)
    ),
    'rsvpsConfirmed', (
      SELECT COUNT(DISTINCT event_id)::int FROM events_rsvps
      WHERE user_id = p_user_id AND confirmed_at IS NOT NULL AND canceled_at IS NULL
    ),
    'rsvpsCanceled', (
      SELECT COUNT(DISTINCT event_id)::int FROM events_rsvps r
      WHERE r.user_id = p_user_id AND r.canceled_at IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM events_rsvps r2
          WHERE r2.user_id = p_user_id
            AND r2.event_id = r.event_id
            AND r2.confirmed_at IS NOT NULL
            AND r2.canceled_at IS NULL
        )
    ),
    'eventsAttended', (
      SELECT COUNT(*)::int FROM events_rsvps
      WHERE user_id = p_user_id
        AND attended_at IS NOT NULL
        AND confirmed_at IS NOT NULL
        AND canceled_at IS NULL
    ),
    'challengesParticipated', (
      SELECT COUNT(DISTINCT cs.challenge_id)::int FROM challenge_submissions cs
      JOIN photos p ON p.id = cs.photo_id
      WHERE cs.user_id = p_user_id AND p.deleted_at IS NULL
    ),
    'challengePhotosAccepted', (
      SELECT COUNT(*)::int FROM challenge_submissions cs
      JOIN photos p ON p.id = cs.photo_id
      WHERE cs.user_id = p_user_id AND cs.status = 'accepted' AND p.deleted_at IS NULL
    ),
    'memberSince', (
      SELECT created_at FROM profiles WHERE id = p_user_id
    ),
    'lastLoggedIn', (
      SELECT last_logged_in FROM profiles WHERE id = p_user_id
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_user_stats(p_user_id uuid) OWNER TO supabase_admin;

--
-- Name: FUNCTION get_user_stats(p_user_id uuid); Type: COMMENT; Schema: public; Owner: supabase_admin
--

COMMENT ON FUNCTION public.get_user_stats(p_user_id uuid) IS 'Returns all user account stats in a single query. Replaces 15+ individual queries. Used by /api/account/stats.';


--
-- Name: global_search(text, integer, text[]); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.global_search(search_query text, result_limit integer DEFAULT 20, search_types text[] DEFAULT ARRAY['albums'::text, 'photos'::text, 'members'::text, 'events'::text, 'tags'::text, 'scene-events'::text, 'challenges'::text]) RETURNS TABLE(entity_type text, entity_id text, title text, subtitle text, image_url text, image_blurhash text, url text, rank real)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH search_tsquery AS (
    SELECT to_tsquery('english',
      regexp_replace(
        regexp_replace(search_query, '\s+', ' & ', 'g'),
        '(\w+)', '\1:*', 'g'
      )
    ) AS query
  ),
  all_results AS (
    SELECT
      'members'::text AS entity_type,
      p.id::text AS entity_id,
      COALESCE(p.full_name, p.nickname, 'Unknown') AS title,
      CASE WHEN p.nickname IS NOT NULL THEN '@' || p.nickname ELSE '' END AS subtitle,
      p.avatar_url AS image_url,
      NULL::text AS image_blurhash,
      CASE WHEN p.nickname IS NOT NULL THEN '/@' || p.nickname ELSE NULL END AS url,
      ts_rank(p.search_vector, sq.query) AS rank
    FROM profiles p
    CROSS JOIN search_tsquery sq
    WHERE 'members' = ANY(search_types)
      AND p.suspended_at IS NULL
      AND p.nickname IS NOT NULL
      AND p.search_vector @@ sq.query

    UNION ALL

    SELECT
      'albums'::text,
      a.id::text,
      a.title,
      COALESCE(a.description, 'Album'),
      a.cover_image_url,
      NULL::text,
      CASE
        WHEN p.nickname IS NOT NULL THEN '/@' || p.nickname || '/album/' || a.slug
        WHEN a.event_id IS NOT NULL THEN '/events/' || (SELECT slug FROM events WHERE id = a.event_id) || '#photos'
        ELSE NULL
      END,
      ts_rank(a.search_vector, sq.query)
    FROM albums a
    LEFT JOIN profiles p ON p.id = a.user_id
    CROSS JOIN search_tsquery sq
    WHERE 'albums' = ANY(search_types)
      AND a.is_public = true
      AND a.deleted_at IS NULL
      AND (a.is_suspended = false OR a.is_suspended IS NULL)
      AND (p.suspended_at IS NULL OR p.id IS NULL)
      AND a.search_vector @@ sq.query

    UNION ALL

    SELECT
      'photos'::text,
      ph.id::text,
      COALESCE(ph.title, 'Untitled Photo'),
      COALESCE(ph.description, ''),
      ph.url,
      ph.blurhash,
      CASE WHEN p.nickname IS NOT NULL THEN '/@' || p.nickname || '/photo/' || ph.short_id ELSE NULL END,
      ts_rank(ph.search_vector, sq.query)
    FROM photos ph
    JOIN profiles p ON p.id = ph.user_id
    CROSS JOIN search_tsquery sq
    WHERE 'photos' = ANY(search_types)
      AND ph.is_public = true
      AND ph.deleted_at IS NULL
      AND p.suspended_at IS NULL
      AND ph.search_vector @@ sq.query

    UNION ALL

    SELECT
      'events'::text,
      e.id::text,
      COALESCE(e.title, 'Untitled Event'),
      COALESCE(e.location, ''),
      e.cover_image,
      NULL::text,
      '/events/' || e.slug,
      ts_rank(e.search_vector, sq.query)
    FROM events e
    CROSS JOIN search_tsquery sq
    WHERE 'events' = ANY(search_types)
      AND e.search_vector @@ sq.query

    UNION ALL

    SELECT
      'scene-events'::text,
      se.id::text,
      se.title,
      COALESCE(se.category || ' • ' || se.location_city, se.location_city),
      se.cover_image_url,
      se.image_blurhash,
      '/scene/' || se.slug,
      ts_rank(se.search_vector, sq.query)
    FROM scene_events se
    CROSS JOIN search_tsquery sq
    WHERE 'scene-events' = ANY(search_types)
      AND se.deleted_at IS NULL
      AND se.search_vector @@ sq.query

    UNION ALL

    SELECT
      'challenges'::text,
      c.id::text,
      c.title,
      LEFT(c.prompt, 200),
      c.cover_image_url,
      c.image_blurhash,
      '/challenges/' || c.slug,
      CASE
        WHEN c.title ILIKE search_query || '%' THEN 1.0::real
        WHEN c.title ILIKE '%' || search_query || '%' THEN 0.8::real
        WHEN c.prompt ILIKE '%' || search_query || '%' THEN 0.5::real
        ELSE 0.1::real
      END
    FROM challenges c
    WHERE 'challenges' = ANY(search_types)
      AND c.is_active = true
      AND (
        c.title ILIKE '%' || search_query || '%'
        OR c.prompt ILIKE '%' || search_query || '%'
      )

    UNION ALL

    SELECT
      'tags'::text,
      t.name,
      t.name,
      COALESCE(t.count, 0)::text || ' photo' || CASE WHEN COALESCE(t.count, 0) = 1 THEN '' ELSE 's' END,
      NULL::text,
      NULL::text,
      '/gallery/tag/' || t.name,
      CASE
        WHEN t.name ILIKE search_query || '%' THEN 1.0::real
        WHEN t.name ILIKE '%' || search_query || '%' THEN 0.5::real
        ELSE 0.1::real
      END
    FROM tags t
    WHERE 'tags' = ANY(search_types)
      AND (t.name ILIKE search_query || '%' OR t.name ILIKE '%' || search_query || '%')
  )
  SELECT
    entity_type,
    entity_id,
    title,
    subtitle,
    image_url,
    image_blurhash,
    url,
    rank
  FROM all_results
  WHERE url IS NOT NULL
  ORDER BY rank DESC, title ASC
  LIMIT result_limit;
$$;


ALTER FUNCTION public.global_search(search_query text, result_limit integer, search_types text[]) OWNER TO supabase_admin;

--
-- Name: FUNCTION global_search(search_query text, result_limit integer, search_types text[]); Type: COMMENT; Schema: public; Owner: supabase_admin
--

COMMENT ON FUNCTION public.global_search(search_query text, result_limit integer, search_types text[]) IS 'Unified full-text search across albums, photos, members, events, scene events, challenges, and tags. SECURITY DEFINER with explicit public-only filters.';


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'name', ''),
    NULL,
    COALESCE(NEW.raw_user_meta_data->>'avatar_url', NEW.raw_user_meta_data->>'picture'),
    NOW(),
    NOW()
  );
  RETURN NEW;
EXCEPTION
  WHEN unique_violation THEN
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.handle_new_user() OWNER TO supabase_admin;

--
-- Name: increment_view_count(text, uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.increment_view_count(p_entity_type text, p_entity_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF p_entity_type = 'photo' THEN
    IF NOT EXISTS (
      SELECT 1 FROM photos
      WHERE id = p_entity_id
        AND is_public = true
        AND deleted_at IS NULL
    ) THEN
      RETURN;
    END IF;

    UPDATE photos SET view_count = view_count + 1 WHERE id = p_entity_id;
  ELSIF p_entity_type = 'album' THEN
    IF NOT EXISTS (
      SELECT 1 FROM albums
      WHERE id = p_entity_id
        AND is_public = true
        AND deleted_at IS NULL
        AND COALESCE(is_suspended, false) = false
    ) THEN
      RETURN;
    END IF;

    UPDATE albums SET view_count = view_count + 1 WHERE id = p_entity_id;
  END IF;
END;
$$;


ALTER FUNCTION public.increment_view_count(p_entity_type text, p_entity_id uuid) OWNER TO supabase_admin;

--
-- Name: FUNCTION increment_view_count(p_entity_type text, p_entity_id uuid); Type: COMMENT; Schema: public; Owner: supabase_admin
--

COMMENT ON FUNCTION public.increment_view_count(p_entity_type text, p_entity_id uuid) IS 'Increments view_count and logs individual view events for weekly trending queries';


--
-- Name: invite_to_shared_album(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.invite_to_shared_album(p_album_id uuid, p_user_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_owner_id uuid;
  v_target_id uuid;
  v_created int := 0;
  v_skipped_member int := 0;
  v_skipped_pending int := 0;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT a.user_id INTO v_owner_id
  FROM "public"."albums" a
  WHERE a.id = p_album_id AND a.is_shared = true AND a.deleted_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Shared album not found';
  END IF;

  IF v_owner_id IS NULL THEN
    RAISE EXCEPTION 'Event albums do not support invites';
  END IF;

  IF v_owner_id <> v_user_id AND NOT (SELECT is_admin FROM "public"."profiles" WHERE id = v_user_id) THEN
    RAISE EXCEPTION 'Only the album owner can invite members';
  END IF;

  FOREACH v_target_id IN ARRAY p_user_ids
  LOOP
    IF v_target_id = v_owner_id THEN
      CONTINUE;
    END IF;
    IF EXISTS (
      SELECT 1 FROM "public"."shared_album_members" m
      WHERE m.album_id = p_album_id AND m.user_id = v_target_id
    ) THEN
      v_skipped_member := v_skipped_member + 1;
      CONTINUE;
    END IF;
    IF EXISTS (
      SELECT 1 FROM "public"."shared_album_requests" r
      WHERE r.album_id = p_album_id AND r.user_id = v_target_id AND r.status = 'pending'
    ) THEN
      v_skipped_pending := v_skipped_pending + 1;
      CONTINUE;
    END IF;
    VALUES (p_album_id, v_target_id, 'invite', v_user_id, 'pending');
    v_created := v_created + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'created', v_created,
    'skipped_existing_member', v_skipped_member,
    'skipped_pending', v_skipped_pending
  );
END;
$$;


