--
-- Name: prevent_private_challenge_photo(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.prevent_private_challenge_photo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    -- If changing is_public from true to false
    IF OLD.is_public = true AND NEW.is_public = false THEN
        -- Check if photo has any accepted challenge submissions
        IF EXISTS (
            SELECT 1 FROM "public"."challenge_submissions"
            WHERE photo_id = NEW.id
              AND status = 'accepted'
        ) THEN
            RAISE EXCEPTION 'Cannot make photo private: it is part of an accepted challenge submission. Withdraw from the challenge first.';
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.prevent_private_challenge_photo() OWNER TO supabase_admin;

--
-- Name: FUNCTION prevent_private_challenge_photo(); Type: COMMENT; Schema: public; Owner: supabase_admin
--

COMMENT ON FUNCTION public.prevent_private_challenge_photo() IS 'Prevents photos with accepted challenge submissions from being made private';


--
-- Name: protect_albums_moderation_columns(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.protect_albums_moderation_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN NEW;
  END IF;

  IF pg_catalog.pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;

  IF NOT public.is_admin() THEN
    IF NEW.is_suspended IS DISTINCT FROM OLD.is_suspended
       OR NEW.suspended_at IS DISTINCT FROM OLD.suspended_at
       OR NEW.suspended_by IS DISTINCT FROM OLD.suspended_by
       OR NEW.suspension_reason IS DISTINCT FROM OLD.suspension_reason THEN
      RAISE EXCEPTION 'Cannot modify album suspension fields';
    END IF;

    IF NEW.likes_count IS DISTINCT FROM OLD.likes_count
       OR NEW.view_count IS DISTINCT FROM OLD.view_count THEN
      RAISE EXCEPTION 'Cannot modify album engagement counters';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.protect_albums_moderation_columns() OWNER TO supabase_admin;

