--
-- Name: challenge_photos; Type: VIEW; Schema: public; Owner: supabase_admin
--

CREATE VIEW public.challenge_photos WITH (security_invoker='on') AS
 SELECT cs.challenge_id,
    cs.photo_id,
    cs.user_id,
    cs.submitted_at,
    cs.reviewed_at,
    p.url,
    p.width,
    p.height,
    p.title,
    p.blurhash,
    p.short_id,
    pr.nickname AS profile_nickname,
    pr.full_name AS profile_full_name,
    pr.avatar_url AS profile_avatar_url
   FROM ((public.challenge_submissions cs
     JOIN public.photos p ON ((p.id = cs.photo_id)))
     JOIN public.profiles pr ON ((pr.id = cs.user_id)))
  WHERE ((cs.status = 'accepted'::text) AND (p.deleted_at IS NULL) AND (pr.suspended_at IS NULL) AND (pr.deletion_scheduled_at IS NULL));


ALTER TABLE public.challenge_photos OWNER TO supabase_admin;

--
-- Name: VIEW challenge_photos; Type: COMMENT; Schema: public; Owner: supabase_admin
--

COMMENT ON VIEW public.challenge_photos IS 'Accepted challenge photos with profile data for attribution (excludes suspended/deleted users)';


