-- Name: objects Admins can delete email assets; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Admins can delete email assets" ON storage.objects FOR DELETE TO authenticated USING (((bucket_id = 'email-assets'::text) AND (EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.is_admin = true))))));


